import {
    Button,
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
    cn,
} from '@schemastud/ui';
import { ArrowUpRight, CheckCircle2, ExternalLink, Sparkles, XCircle } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { errorMessage } from './format';
import {
    useEntitlements,
    useSubscription,
    useSubscriptionCheckout,
    useSubscriptionPortal,
} from './commerce-hooks';
import { useCommerceCan, useCommerceNavigate } from './commerce-provider';
import type {
    EntitlementRecord,
    LifecycleState,
    SourceFacet,
    Subscription,
    SubscriptionView,
} from './commerce-types';
import { ENTITLEMENT_SOURCE_FACETS, entitlementSourceLabel } from './vocabulary';
import { SurfaceHeading } from './SurfaceHeading';

/**
 * Subscription & plan (Frame OS ticket 21 — promoted from the app's settings `SubscriptionPage`).
 * Single-pane, read-only for every tenant member: a resolved PlanHeaderCard (with folded lifecycle
 * badge) stacked above the resolved, faceted EntitlementGrid. Mutations delegate to Stripe (hosted
 * checkout / Customer Portal) — no in-app plan-mutation form.
 *
 * ADR-0116 CAVEAT: this surface lands in beam-commerce as the current tier verdict; ADR-0116 leaves
 * the DTO-first package placement of EntitlementGrid/UpsellSheet open. It owns its react-query data
 * logic + presentation; the host supplies the transport + navigation (via <CommerceProvider>) and
 * the optional post-checkout signal (host-router-owned) through props.
 */

function LifecycleBadge({ state, endsAt, awaitingPayment }: { state: LifecycleState; endsAt: string | null; awaitingPayment: boolean }) {
    // A paid plan that is unfunded resolves the free plan's entitlements (M14, I1): it is not Active.
    if (awaitingPayment && state !== 'lapsed') {
        return (
            <span className="inline-flex items-center gap-1.5 rounded-md border border-warning/40 bg-warning/10 px-2 py-1 text-xs font-medium text-warning-foreground">
                <span className="size-1.5 rounded-full bg-warning" /> Awaiting payment
            </span>
        );
    }
    // No plan subscription at all (APP-10): absence is a declared value, and it is not Active.
    if (state === 'none') {
        return (
            <span className="inline-flex items-center gap-1.5 rounded-md border border-border bg-muted px-2 py-1 text-xs font-medium text-muted-foreground">
                No plan
            </span>
        );
    }
    if (state === 'lapsed') {
        return (
            <span className="inline-flex items-center gap-1.5 rounded-md border border-destructive/40 bg-destructive/10 px-2 py-1 text-xs font-medium text-destructive">
                <XCircle className="size-3.5" /> Lapsed
            </span>
        );
    }
    if (state === 'cancels_at_period_end') {
        return (
            <span className="inline-flex items-center gap-1.5 rounded-md border border-warning/40 bg-warning/10 px-2 py-1 text-xs font-medium text-warning-foreground">
                <span className="size-1.5 rounded-full bg-warning" /> Active until {endsAt ?? '—'} ·
                cancels
            </span>
        );
    }
    return (
        <span className="inline-flex items-center gap-1.5 rounded-md border border-primary/30 bg-primary/5 px-2 py-1 text-xs font-medium text-foreground">
            <CheckCircle2 className="size-3.5 text-primary" /> Active
        </span>
    );
}

/**
 * How the subscription is funded, stated from the declared value (purchase-walkthrough M14). Never inferred from a
 * missing price id: a plan with no price is not thereby a "Free tier".
 */
function fundingLabel(sub: Subscription | null): string {
    if (sub?.awaitingPayment) return 'Awaiting payment';
    switch (sub?.funding) {
        case 'card':
            return 'Card · managed in Stripe';
        case 'invoice':
            return 'Invoiced';
        case 'comp':
            return sub.comp ? `Comped: ${sub.comp.reason}${sub.comp.expiresAt ? ` (until ${sub.comp.expiresAt.slice(0, 10)})` : ''}` : 'Comped';
        case 'none':
            return 'Not funded';
        default:
            return 'Not recorded';
    }
}

function PlanHeaderCard({ view }: { view: SubscriptionView }) {
    const sub = view.subscription;
    // Declared on the wire (SubscriptionViewData::$lifecycle, APP-10), never derived here.
    const state = view.lifecycle;
    const lapsed = state === 'lapsed';
    const awaitingPayment = sub?.awaitingPayment === true;
    const plan = sub?.plan;
    const endsAt = sub?.endedAt ? sub.endedAt.slice(0, 7) : null;

    return (
        <Card>
            <CardHeader>
                <div className="flex items-start justify-between gap-3">
                    <div className="space-y-1">
                        <div className="flex items-center gap-2">
                            <CardTitle>{plan?.name ?? 'No plan'}</CardTitle>
                            <LifecycleBadge state={state} endsAt={endsAt} awaitingPayment={awaitingPayment} />
                        </div>
                        <CardDescription>
                            {plan?.description ?? 'You have no recurring subscription.'}
                        </CardDescription>
                    </div>
                </div>
            </CardHeader>
            <CardContent>
                <div className="grid gap-4 sm:grid-cols-3">
                    <div>
                        <div className="text-xs text-muted-foreground">Funding</div>
                        <div className="text-lg font-semibold">
                            <span className="text-muted-foreground">{fundingLabel(sub)}</span>
                        </div>
                    </div>
                    <div>
                        <div className="text-xs text-muted-foreground">Commitment</div>
                        <div className="text-lg font-semibold">
                            {sub?.commitmentMonths
                                ? `${sub.commitmentMonths} ${sub.commitmentMonths === 1 ? 'month' : 'months'}`
                                : 'Month-to-month'}
                        </div>
                    </div>
                    <div>
                        <div className="text-xs text-muted-foreground">
                            {lapsed ? 'Coverage ended' : 'Billable window'}
                        </div>
                        <div
                            className={cn(
                                'font-mono text-sm',
                                lapsed ? 'text-destructive' : 'text-foreground',
                            )}
                        >
                            {sub?.earliestBillablePeriod ?? '—'} → {sub?.latestBillablePeriod ?? '—'}
                        </div>
                    </div>
                </div>
                {lapsed && (
                    <p className="mt-4 flex gap-2 rounded-md border border-destructive/30 bg-destructive/[0.06] p-3 text-sm text-destructive">
                        <XCircle className="mt-0.5 size-4 flex-none" />
                        <span>
                            This subscription is outside its active window —{' '}
                            <b>entitlements and the spending cap are revoked</b> until you
                            re-subscribe. Re-activate via the Customer Portal.
                        </span>
                    </p>
                )}
            </CardContent>
        </Card>
    );
}

function SourceBadge({ source }: { source: string }) {
    const style =
        source === 'tenant'
            ? 'border-primary/30 bg-primary/5 text-foreground'
            : source === 'plan'
              ? 'border-border bg-muted/60 text-muted-foreground'
              : 'border-dashed border-border bg-transparent text-muted-foreground';
    return (
        <span
            className={cn(
                'inline-flex items-center rounded border px-1.5 py-0.5 text-[10px] tracking-wide',
                style,
            )}
        >
            <span>{entitlementSourceLabel(source)}</span>
            <span className="ml-1 font-mono text-[9px] normal-case opacity-70">{source}</span>
        </span>
    );
}

function EntitlementGrid({
    entitlements,
    labels,
    lapsed,
}: {
    entitlements: EntitlementRecord[];
    labels: Record<string, string>;
    lapsed: boolean;
}) {
    const [facet, setFacet] = useState<SourceFacet>('all');
    const rows = useMemo(
        () => (facet === 'all' ? entitlements : entitlements.filter((e) => e.source === facet)),
        [entitlements, facet],
    );

    return (
        <Card>
            <CardHeader>
                <div className="flex items-start justify-between gap-3">
                    <div>
                        <CardTitle>Resolved entitlements</CardTitle>
                        <CardDescription>
                            What&apos;s on your plan — the RESOLVED map (not plan text), cascaded{' '}
                            <span className="font-mono text-xs">default → plan → tenant</span>.
                        </CardDescription>
                    </div>
                </div>
                <div className="flex flex-wrap gap-1.5 pt-1">
                    {ENTITLEMENT_SOURCE_FACETS.map((f) => (
                        <button
                            key={f.key}
                            type="button"
                            onClick={() => setFacet(f.key)}
                            className={cn(
                                'rounded-full border px-2.5 py-0.5 text-xs transition-colors',
                                facet === f.key
                                    ? 'border-primary/40 bg-primary/10 text-foreground'
                                    : 'border-border text-muted-foreground hover:bg-muted/60',
                            )}
                        >
                            {f.label}
                        </button>
                    ))}
                </div>
            </CardHeader>
            <CardContent>
                <div>
                    <div className="divide-y rounded-md border">
                        <div data-entitlement-header className="hidden grid-cols-[1fr_auto_auto] gap-4 bg-muted/40 px-3 py-2 text-[11px] font-medium uppercase tracking-wide text-muted-foreground sm:grid">
                            <span>Capability</span>
                            <span className="text-right">State</span>
                            <span className="text-right">Source</span>
                        </div>
                        {rows.length === 0 && (
                            <div className="px-3 py-6 text-center text-sm text-muted-foreground">
                                No capabilities in this facet.
                            </div>
                        )}
                        {rows.map((e) => {
                            const on = e.enabled && !lapsed;
                            return (
                                <div
                                    key={e.capability}
                                    data-entitlement-row
                                    className="grid grid-cols-1 items-center gap-2 px-3 py-2.5 sm:grid-cols-[1fr_auto_auto] sm:gap-4"
                                >
                                    <div className="min-w-0">
                                        <span className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground sm:hidden">Capability</span>
                                        <div
                                            className={cn(
                                                'truncate text-sm',
                                                !on && 'text-muted-foreground line-through',
                                            )}
                                        >
                                            {labels[e.capability] ?? e.capability}
                                        </div>
                                        <div className="font-mono text-[10px] text-muted-foreground">
                                            {e.capability}
                                        </div>
                                    </div>
                                    <div className="flex items-center justify-between gap-3 sm:justify-end">
                                        <span className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground sm:hidden">State</span>
                                        <span
                                            className={cn(
                                                'inline-flex items-center gap-1.5 text-xs',
                                                on ? 'text-foreground' : 'text-muted-foreground',
                                            )}
                                        >
                                            <span
                                                className={cn(
                                                    'size-1.5 rounded-full',
                                                    on ? 'bg-primary' : 'bg-muted-foreground/40',
                                                )}
                                            />
                                            {on
                                                ? 'Enabled'
                                                : lapsed && e.enabled
                                                  ? 'Revoked'
                                                  : 'Off'}
                                        </span>
                                    </div>
                                    <div className="flex items-center justify-between gap-3 sm:justify-end">
                                        <span className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground sm:hidden">Source</span>
                                        <SourceBadge source={e.source} />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

/**
 * The optional post-checkout signal — host-router-owned (splicewire reads it off `?checkout=` via
 * react-router's useSearchParams). The package stays router-blind: the host reads its own URL and
 * passes the signal + a clear callback down. Omitted → no syncing / cancelled notices fire.
 */
export interface CheckoutSignalProps {
    checkoutSignal?: 'success' | 'cancelled' | null;
    onClearCheckoutSignal?: () => void;
    embedded?: boolean;
}

export function SubscriptionSurface({
    checkoutSignal = null,
    onClearCheckoutSignal,
    embedded = false,
}: CheckoutSignalProps = {}) {
    const entitlements = useEntitlements();
    const view = useSubscription();
    const checkout = useSubscriptionCheckout();
    const portal = useSubscriptionPortal();
    const navigate = useCommerceNavigate();
    // The portal and plan checkout are billing WRITES the host gates, each on its own ability: the portal on
    // `billing.manage` (OQ-A2) and plan checkout on the plan op's `plans.checkout` (launch 90ce7f6e). A non-holder is
    // not offered a button that can only 403. The plan and entitlements still read.
    const can = useCommerceCan();
    const canManageBilling = can('billing.manage');
    const canCheckoutPlan = can('plans.checkout');

    // Poll on the success signal: after a Stripe round-trip the internal Subscription syncs async, so
    // refetch until the lifecycle flips rather than trusting a confident-but-stale read. Clears the
    // signal (host-owned) once the plan lands.
    const syncing = checkoutSignal === 'success' && !view.data?.subscription?.active;
    useEffect(() => {
        if (!syncing) return;
        const t = setInterval(() => view.refetch(), 2500);
        return () => clearInterval(t);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [syncing]);
    useEffect(() => {
        if (checkoutSignal === 'success' && view.data?.subscription?.active) {
            onClearCheckoutSignal?.();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [checkoutSignal, view.data?.subscription?.active]);

    const data = view.data;
    const lapsed = data?.lifecycle === 'lapsed';

    const onPortal = () =>
        portal.mutate(undefined, { onSuccess: ({ url }) => navigate(url) });
    const onCheckout = () => {
        // The plans/{id}/op/checkout particle op takes the Plan ID in the path (not a body slug).
        const planId = data?.subscription?.planId;
        if (planId) checkout.mutate(planId, { onSuccess: ({ url }) => navigate(url) });
    };

    // BUY-04 (BQ-2): the pay action is a card setup for a plan that awaits payment (no Stripe price id is involved); it
    // comes first. Otherwise an org with a Stripe customer manages billing in the portal.
    const actions = data?.subscription?.awaitingPayment && data.subscription.planId ? (
        <div className="flex max-w-64 flex-col items-end gap-1">
            <Button
                size="sm"
                onClick={onCheckout}
                disabled={!canCheckoutPlan || checkout.isPending}
                aria-describedby={!canCheckoutPlan ? 'subscription-checkout-refusal' : undefined}
            >
                Subscribe <ArrowUpRight className="size-3.5" />
            </Button>
            {!canCheckoutPlan && (
                <p id="subscription-checkout-refusal" className="text-right text-xs text-muted-foreground">
                    Your role can’t choose a plan. Ask a workspace owner or admin to subscribe.
                </p>
            )}
        </div>
    ) : data?.hasStripeId ? (
        <div className="flex max-w-64 flex-col items-end gap-1">
            <Button
                variant="outline"
                size="sm"
                onClick={onPortal}
                disabled={!canManageBilling || portal.isPending}
                aria-describedby={!canManageBilling ? 'subscription-manage-refusal' : undefined}
            >
                Manage subscription <ExternalLink className="size-3.5" />
            </Button>
            {!canManageBilling && (
                <p id="subscription-manage-refusal" className="text-right text-xs text-muted-foreground">
                    Your role can’t manage billing. Ask a workspace owner or admin to manage the subscription.
                </p>
            )}
        </div>
    ) : null;

    return (
        <div className="space-y-6">
            <div className="flex items-start justify-between gap-4">
                <div>
                    <SurfaceHeading embedded={embedded}>Subscription</SurfaceHeading>
                    <p className="text-sm text-muted-foreground">
                        Your recurring plan and what it entitles you to.
                    </p>
                </div>
                {actions}
            </div>

            {syncing && (
                <div className="flex items-center gap-2 rounded-md border border-border bg-muted/50 px-4 py-2 text-sm text-muted-foreground">
                    <span className="size-1.5 animate-pulse rounded-full bg-primary" />
                    Syncing your plan… changes made in Stripe land here after the webhook is
                    processed — this may take a moment.
                </div>
            )}
            {checkoutSignal === 'cancelled' && (
                <div className="rounded-md border border-border bg-muted/50 px-4 py-2 text-sm text-muted-foreground">
                    Checkout was cancelled — your plan is unchanged.
                </div>
            )}

            {view.isPending && (
                <Card>
                    <CardHeader>
                        <CardTitle>Subscription</CardTitle>
                        <CardDescription>Loading your plan…</CardDescription>
                    </CardHeader>
                </Card>
            )}
            {view.isError && (
                <Card>
                    <CardHeader>
                        <CardTitle>Subscription</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <p className="text-sm text-destructive">
                            {errorMessage(view.error, 'Could not load your subscription.')}
                        </p>
                    </CardContent>
                </Card>
            )}

            {data && (
                <div className="space-y-4">
                    <PlanHeaderCard view={data} />

                    {data.subscription?.awaitingPayment && (
                        <div className="flex items-start gap-3 rounded-md border border-warning/40 bg-warning/[0.06] p-4">
                            <Sparkles className="mt-0.5 size-4 flex-none text-warning" />
                            <div className="space-y-1 text-sm">
                                <div className="font-medium text-foreground">Awaiting payment</div>
                                <p className="text-muted-foreground">
                                    This plan is not paid for yet, so the free plan&apos;s features apply until it is.
                                </p>
                            </div>
                        </div>
                    )}

                    <EntitlementGrid
                        entitlements={entitlements.data ?? []}
                        labels={data.capabilityLabels}
                        lapsed={lapsed}
                    />
                </div>
            )}
        </div>
    );
}
